import type { Texture } from 'ogl';

export type WarpTextLens = 'bulge' | 'pinch' | 'swirl';

export interface WarpTextProps {
  /** The headline text rendered into the WebGL texture. Use `\n` for line breaks. */
  text?: string;
  /** Text fill color before the glass pass. `currentColor` follows the surrounding text color. */
  color?: string;
  /** Amount of ambient glass distortion at rest. */
  warpStrength?: number;
  /** Size of the moving distortion cells. */
  warpScale?: number;
  /** Speed of the ambient undulation. */
  speed?: number;
  /** Radius of the cursor lensing area. */
  pointerInfluence?: number;
  /** Strength of cursor-driven bending and magnification. */
  pointerStrength?: number;
  /** Subtle RGB channel split for the glass edge. */
  refraction?: number;
  /** Color fringing inside the lens and click ripples. 0 is off, 1 is strong. */
  chromatic?: number;
  /** Adds a soft ripple to the pointer lens. */
  ripple?: boolean;
  /** Clicking sends a shockwave ring through the text. */
  clickRipple?: boolean;
  /** How strongly the lens keeps wandering over the text while the cursor is away (0–1). */
  idleDrift?: number;
  /** How the cursor bends the text: magnify, pull inward or twist. */
  lens?: WarpTextLens;
  /** Fades the text in from a strong warp that settles. */
  intro?: boolean;
  /** Raster font size. Numbers are pixels. The text shrinks to fit the container. */
  fontSize?: string | number;
  /** Font weight used when rasterising the text texture. */
  fontWeight?: string | number;
  /** Font family used when rasterising the text texture. */
  fontFamily?: string;
  /** Tracking applied while drawing the text into the texture. */
  letterSpacing?: string | number;
  /** Line height for multi-line text. */
  lineHeight?: string | number;
  class?: string;
}

export interface WarpTextRasterSettings {
  text: string;
  color: string;
  fontSize: string | number;
  fontWeight: string | number;
  fontFamily: string;
  letterSpacing: string | number;
  lineHeight: string | number;
}

export interface WarpTextRaster {
  canvas: HTMLCanvasElement;
  ink: string;
}

export interface WarpTextUniform<T> {
  value: T;
}

export interface WarpTextUniforms {
  [key: string]: WarpTextUniform<unknown>;
  uTextTexture: WarpTextUniform<Texture>;
  uResolution: WarpTextUniform<Float32Array>;
  uPointer: WarpTextUniform<Float32Array>;
  uPointerActive: WarpTextUniform<number>;
  uTime: WarpTextUniform<number>;
  uWarpStrength: WarpTextUniform<number>;
  uWarpScale: WarpTextUniform<number>;
  uSpeed: WarpTextUniform<number>;
  uPointerInfluence: WarpTextUniform<number>;
  uPointerStrength: WarpTextUniform<number>;
  uRefraction: WarpTextUniform<number>;
  uChromatic: WarpTextUniform<number>;
  uRipple: WarpTextUniform<number>;
  uMotion: WarpTextUniform<number>;
  uLens: WarpTextUniform<number>;
  uIntro: WarpTextUniform<number>;
  uReveal: WarpTextUniform<number>;
  uBackdrop: WarpTextUniform<number>;
  uClicks: WarpTextUniform<number[][]>;
}

import type { WarpTextRaster, WarpTextRasterSettings } from './types';

export function getFontValue(value: string | number): string {
  return typeof value === 'number' ? `${value}px` : value;
}

export function smooth(value: number): number {
  return value * value * (3 - 2 * value);
}

export function getLuminance(color: string): number {
  const probe = document.createElement('canvas');
  probe.width = 1;
  probe.height = 1;
  const ctx = probe.getContext('2d', { willReadFrequently: true });
  if (!ctx) return 1;
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, 1, 1);
  const [r = 255, g = 255, b = 255] = ctx.getImageData(0, 0, 1, 1).data;
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
}

function measureLine(
  ctx: CanvasRenderingContext2D,
  line: string,
  letterSpacing: number,
): number {
  const chars = Array.from(line);
  const textWidth = chars.reduce(
    (width, char) => width + ctx.measureText(char).width,
    0,
  );
  return textWidth + Math.max(0, chars.length - 1) * letterSpacing;
}

function drawLine(
  ctx: CanvasRenderingContext2D,
  line: string,
  x: number,
  y: number,
  letterSpacing: number,
): void {
  const chars = Array.from(line);
  let cursor = x - measureLine(ctx, line, letterSpacing) / 2;
  chars.forEach((char, index) => {
    ctx.fillText(char, cursor, y);
    cursor +=
      ctx.measureText(char).width +
      (index === chars.length - 1 ? 0 : letterSpacing);
  });
}

export function buildTextCanvas(
  container: HTMLElement,
  width: number,
  height: number,
  dpr: number,
  settings: WarpTextRasterSettings,
): WarpTextRaster {
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.floor(width * dpr));
  canvas.height = Math.max(1, Math.floor(height * dpr));

  const ctx = canvas.getContext('2d');
  if (!ctx) return { canvas, ink: settings.color };

  const probe = document.createElement('span');
  probe.textContent = settings.text;
  Object.assign(probe.style, {
    position: 'absolute',
    visibility: 'hidden',
    pointerEvents: 'none',
    whiteSpace: 'pre',
    inset: '0 auto auto 0',
    color: settings.color,
    fontFamily: settings.fontFamily,
    fontSize: getFontValue(settings.fontSize),
    fontWeight: String(settings.fontWeight),
    letterSpacing: getFontValue(settings.letterSpacing),
    lineHeight:
      typeof settings.lineHeight === 'number'
        ? String(settings.lineHeight)
        : settings.lineHeight,
  });
  container.appendChild(probe);
  const computed = window.getComputedStyle(probe);
  let fontSizePx = Number.parseFloat(computed.fontSize) || 96;
  const ink = computed.color || settings.color;
  const fontFamily = computed.fontFamily || 'sans-serif';
  const fontWeight = computed.fontWeight || String(settings.fontWeight);
  let letterSpacing =
    computed.letterSpacing === 'normal'
      ? 0
      : Number.parseFloat(computed.letterSpacing) || 0;
  let lineHeight = Number.parseFloat(computed.lineHeight);
  if (!Number.isFinite(lineHeight)) {
    lineHeight =
      fontSizePx *
      (typeof settings.lineHeight === 'number' ? settings.lineHeight : 0.92);
  }
  probe.remove();

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = ink;
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';

  const lines = String(settings.text || '').split('\n');
  const applyFont = () => {
    ctx.font = `${fontWeight} ${fontSizePx}px ${fontFamily}`;
  };
  applyFont();

  const maxWidth = width * 0.86;
  const maxHeight = height * 0.78;
  const widest = Math.max(
    ...lines.map((line) => measureLine(ctx, line, letterSpacing)),
    1,
  );
  const blockHeight = Math.max(lineHeight * lines.length, 1);
  const fit = Math.min(1, maxWidth / widest, maxHeight / blockHeight);

  if (fit < 1) {
    fontSizePx *= fit;
    letterSpacing *= fit;
    lineHeight *= fit;
    applyFont();
  }

  const startY = height / 2 - (lineHeight * (lines.length - 1)) / 2;
  lines.forEach((line, index) => {
    drawLine(ctx, line, width / 2, startY + index * lineHeight, letterSpacing);
  });

  return { canvas, ink };
}

export const WARP_TEXT_VERTEX = `#version 300 es
in vec2 position;
in vec2 uv;
out vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

export const WARP_TEXT_FRAGMENT = `#version 300 es
precision highp float;

uniform sampler2D uTextTexture;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uPointerActive;
uniform float uTime;
uniform float uWarpStrength;
uniform float uWarpScale;
uniform float uSpeed;
uniform float uPointerInfluence;
uniform float uPointerStrength;
uniform float uRefraction;
uniform float uChromatic;
uniform float uRipple;
uniform float uMotion;
uniform float uLens;
uniform float uIntro;
uniform float uReveal;
uniform float uBackdrop;
uniform vec4 uClicks[4];

in vec2 vUv;
out vec4 fragColor;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);

  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));

  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float value = 0.0;
  float amplitude = 0.5;
  for (int i = 0; i < 4; i++) {
    value += amplitude * noise(p);
    p *= 2.02;
    amplitude *= 0.5;
  }
  return value;
}

vec4 sampleText(vec2 uv) {
  if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
    return vec4(0.0);
  }
  return texture(uTextTexture, uv);
}

void main() {
  vec2 uv = vUv;
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float time = uTime * uSpeed;
  float scale = max(uWarpScale, 0.001);

  vec2 drift = vec2(time * 0.055, -time * 0.045);
  float n1 = fbm(uv * scale * 3.1 + drift);
  float n2 = fbm((uv + 19.17) * scale * 3.4 - drift.yx);
  vec2 ambient = (vec2(n1, n2) - 0.5) * (uWarpStrength * 0.045 * uMotion + uIntro * 0.18);

  vec2 pointerDelta = uv - uPointer;
  vec2 aspectDelta = vec2(pointerDelta.x * aspect, pointerDelta.y);
  float dist = length(aspectDelta);
  float radius = max(uPointerInfluence, 0.001);
  float t = clamp(dist / radius, 0.0, 1.0);
  float lens = smoothstep(radius, 0.0, dist) * uPointerActive;
  float bulge = t * (1.0 - t) * (1.0 - t) * 6.75 * uPointerActive;
  vec2 dir = dist > 0.0001 ? vec2(aspectDelta.x / aspect, aspectDelta.y) / dist : vec2(0.0);

  float rippleWave = sin(dist * 28.0 - time * 4.2) * 0.5 + 0.5;
  float rippleRing = (rippleWave - 0.5) * uRipple;
  vec2 pointerWarp = dir * rippleRing * bulge * uPointerStrength * 0.016;

  if (uLens > 1.5) {
    float twist = (1.0 - t) * (1.0 - t) * uPointerActive * uPointerStrength * 2.4;
    float s = sin(twist);
    float c = cos(twist);
    vec2 turned = vec2(aspectDelta.x * c - aspectDelta.y * s, aspectDelta.x * s + aspectDelta.y * c);
    pointerWarp += vec2(turned.x / aspect, turned.y) - pointerDelta;
  } else {
    float side = uLens > 0.5 ? -1.0 : 1.0;
    pointerWarp -= dir * side * bulge * uPointerStrength * 0.045;
  }

  vec2 shock = vec2(0.0);
  float shockLight = 0.0;
  for (int i = 0; i < 4; i++) {
    vec4 click = uClicks[i];
    if (click.w <= 0.0) continue;
    vec2 clickDelta = uv - click.xy;
    vec2 clickAspect = vec2(clickDelta.x * aspect, clickDelta.y);
    float clickDist = length(clickAspect);
    float age = click.z;
    float offset = (clickDist - age * 0.9) / (0.06 + age * 0.06);
    float fade = 1.0 - smoothstep(0.0, 1.6, age);
    float energy = exp(-offset * offset) * fade * smoothstep(0.0, 0.08, age) * click.w;
    vec2 clickDir = clickDist > 0.0001 ? vec2(clickAspect.x / aspect, clickAspect.y) / clickDist : vec2(0.0);
    shock -= clickDir * offset * energy * 0.09;
    shockLight += energy;
  }

  vec2 bend = pointerWarp + shock;
  vec2 rest = uv + ambient;
  vec2 splitDir = ambient + bend;
  float splitLen = length(splitDir);
  splitDir = splitLen > 0.00001 ? splitDir / splitLen : vec2(0.7071, 0.7071);
  vec2 split = splitDir * uRefraction * 0.16 * (0.35 + lens * 1.65 + uIntro * 3.0);
  float dispersion = uChromatic * 0.5;

  vec3 ink = vec3(0.0);
  vec3 cover = vec3(0.0);
  vec3 weight = vec3(0.0);
  for (int i = 0; i < 7; i++) {
    float k = 1.0 - float(i) / 3.0;
    vec4 tap = sampleText(rest + bend * (1.0 + dispersion * k) + split * k);
    vec3 band = vec3(max(k, 0.0), 1.0 - abs(k), max(-k, 0.0));
    ink += tap.rgb * band;
    cover += tap.a * band;
    weight += band;
  }
  ink /= weight;
  cover /= weight;
  float a = max(max(cover.r, cover.g), cover.b);
  vec3 color = ink + (a - cover) * uBackdrop;
  color = min(color + (lens + shockLight * 0.5) * cover.g * 0.055, vec3(a));
  fragColor = vec4(color, a) * uReveal;
}
`;
